PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (id TEXT PRIMARY KEY, tg_id TEXT UNIQUE NOT NULL, username TEXT, is_premium INTEGER DEFAULT 0, points INTEGER DEFAULT 0, predictions_count INTEGER DEFAULT 0, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), tours_played INTEGER DEFAULT 0, ton_wallet TEXT, ton_consent INTEGER DEFAULT 0, ton_earned REAL DEFAULT 0, ton_distributed REAL DEFAULT 0, fav_team TEXT, auth_source TEXT, guest_token TEXT, merged_into TEXT, ref_source TEXT);
CREATE TABLE matches (id TEXT PRIMARY KEY, home_team TEXT NOT NULL, away_team TEXT NOT NULL, date TEXT, time TEXT, round TEXT, status TEXT DEFAULT 'upcoming', home_score INTEGER, away_score INTEGER, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), grp TEXT, venue TEXT, card_home TEXT, card_away TEXT, is_active INTEGER DEFAULT 1, week_id TEXT, result TEXT, match_date_utc TEXT, match_date_local TEXT, league TEXT, source TEXT, source_id TEXT, crest_home TEXT, crest_away TEXT, code_home TEXT, code_away TEXT);
CREATE TABLE predictions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, match_id TEXT NOT NULL, prediction_type TEXT NOT NULL, predicted_score TEXT, points_earned INTEGER, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE rewards (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, week INTEGER, points INTEGER, ton_amount REAL, status TEXT DEFAULT 'pending', claimed_at TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE bets (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, match_id TEXT NOT NULL, week_id TEXT NOT NULL, prediction TEXT NOT NULL, score_home INTEGER NOT NULL, score_away INTEGER NOT NULL, points_earned INTEGER, created_at TEXT, updated_at TEXT, UNIQUE(user_id, match_id));
CREATE TABLE champions (id INTEGER PRIMARY KEY AUTOINCREMENT, week_id TEXT NOT NULL, user_id TEXT NOT NULL, username TEXT, total_points INTEGER DEFAULT 0, correct_outcomes INTEGER DEFAULT 0, correct_scores INTEGER DEFAULT 0, matches_predicted INTEGER DEFAULT 0, last_bet_at TEXT, rank INTEGER, ton_earned REAL DEFAULT 0.0, computed_at TEXT, UNIQUE(week_id, user_id));
CREATE TABLE leaderboard (user_id TEXT PRIMARY KEY, username TEXT, total_points INTEGER DEFAULT 0, correct_outcomes INTEGER DEFAULT 0, correct_scores INTEGER DEFAULT 0, weeks_played INTEGER DEFAULT 0, weeks_won INTEGER DEFAULT 0, ton_earned REAL DEFAULT 0.0, ton_distributed REAL DEFAULT 0.0, updated_at TEXT);
CREATE TABLE premium_purchases (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL,
  tg_id TEXT NOT NULL,
  stars_amount INTEGER NOT NULL,
  telegram_payment_charge_id TEXT NOT NULL UNIQUE,
  invoice_payload TEXT,
  purchased_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE bronze_adjustments (
  id           TEXT PRIMARY KEY,
  week_id      TEXT NOT NULL,
  user_id      TEXT NOT NULL,
  points_delta INTEGER NOT NULL,
  reason       TEXT,
  created_at   TEXT DEFAULT (datetime('now'))
);
CREATE TABLE silver_dim_user (
  user_id     TEXT PRIMARY KEY,
  tg_id       TEXT,
  username    TEXT,
  is_premium  INTEGER DEFAULT 0,
  fav_team    TEXT,
  is_internal INTEGER DEFAULT 0
);
CREATE TABLE silver_dim_week (
  week_id   TEXT PRIMARY KEY,
  label     TEXT,
  weekstart TEXT
);
CREATE TABLE silver_dim_team (
  team TEXT PRIMARY KEY,
  code TEXT
);
CREATE TABLE silver_fact_bet (
  user_id      TEXT,
  match_id     TEXT,
  week_id      TEXT,
  pred_outcome TEXT,
  pred_home    INTEGER,
  pred_away    INTEGER,
  updated_at   TEXT,
  PRIMARY KEY (user_id, match_id)
);
CREATE TABLE silver_fact_result (
  match_id   TEXT PRIMARY KEY,
  week_id    TEXT,
  home_team  TEXT,
  away_team  TEXT,
  home_score INTEGER,
  away_score INTEGER,
  outcome    TEXT,
  is_final   INTEGER DEFAULT 0
);
CREATE TABLE silver_fact_score (
  user_id            TEXT,
  match_id           TEXT,
  week_id            TEXT,
  points_base        INTEGER,
  is_correct_outcome INTEGER,
  is_correct_score   INTEGER,
  PRIMARY KEY (user_id, match_id)
);
CREATE TABLE gold_champions (
  week_id           TEXT,
  user_id           TEXT,
  username          TEXT,
  total_points      INTEGER,
  correct_outcomes  INTEGER,
  correct_scores    INTEGER,
  matches_predicted INTEGER,
  adjustment_points INTEGER DEFAULT 0,
  last_bet_at       TEXT,
  rank              INTEGER,
  computed_at       TEXT,
  PRIMARY KEY (week_id, user_id)
);
CREATE TABLE gold_leaderboard (
  user_id          TEXT PRIMARY KEY,
  username         TEXT,
  is_premium       INTEGER DEFAULT 0,
  fav_team         TEXT,
  total_points     INTEGER,
  correct_outcomes INTEGER,
  correct_scores   INTEGER,
  weeks_played     INTEGER,
  weeks_won        INTEGER,
  computed_at      TEXT
);
CREATE TABLE bronze_match_results (
  source     TEXT,
  source_id  TEXT,
  date_utc   TEXT,
  home_team  TEXT,
  away_team  TEXT,
  home_score INTEGER,
  away_score INTEGER,
  status     TEXT,
  fetched_at TEXT,
  PRIMARY KEY (source, source_id)
);
CREATE TABLE bronze_fixtures (
  source      TEXT NOT NULL,          -- 'espn'
  source_id   TEXT NOT NULL,          -- feed event id, stable across pulls
  league      TEXT NOT NULL,          -- our slug, e.g. 'eng.1'
  league_name TEXT,                   -- human label from the feed
  kickoff_utc TEXT NOT NULL,          -- ISO 8601 Z
  home_team   TEXT NOT NULL,
  away_team   TEXT NOT NULL,
  home_code   TEXT,                   -- feed abbreviation
  away_code   TEXT,
  home_crest  TEXT,                   -- logo URL — club football has no TEAM_CARDS entry
  away_crest  TEXT,
  status      TEXT,                   -- 'scheduled' | 'live' | 'finished'
  fetched_at  TEXT,
  PRIMARY KEY (source, source_id)
);
CREATE TABLE weeks (
  week_id      TEXT PRIMARY KEY,
  starts_at    TEXT NOT NULL,         -- Monday 00:00 UTC
  ends_at      TEXT NOT NULL,         -- Sunday 23:59:59 UTC
  status       TEXT NOT NULL DEFAULT 'draft',  -- draft | published | closed
  published_at TEXT,
  created_at   TEXT DEFAULT (datetime('now'))
);
CREATE TABLE weekly_prizes (
  id        TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  week_id   TEXT NOT NULL,
  rank      INTEGER NOT NULL,
  user_id   TEXT NOT NULL,
  stars     INTEGER NOT NULL,           -- 100 for 1st, 50 for 2nd
  status    TEXT NOT NULL DEFAULT 'owed',  -- owed | paid | void
  awarded_at TEXT DEFAULT (datetime('now')),
  paid_at   TEXT,
  note      TEXT,
  UNIQUE(week_id, rank)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_users_tg_id ON users(tg_id);
CREATE INDEX idx_predictions_user_id ON predictions(user_id);
CREATE INDEX idx_predictions_match_id ON predictions(match_id);
CREATE INDEX idx_rewards_user_id ON rewards(user_id);
CREATE INDEX idx_premium_purchases_user_id ON premium_purchases(user_id);
CREATE INDEX idx_premium_purchases_tg_id ON premium_purchases(tg_id);
CREATE INDEX idx_bronze_fixtures_kickoff ON bronze_fixtures (kickoff_utc);
CREATE INDEX idx_matches_week ON matches (week_id);
CREATE INDEX idx_weekly_prizes_user ON weekly_prizes (user_id);
CREATE INDEX idx_weekly_prizes_week ON weekly_prizes (week_id);
CREATE UNIQUE INDEX idx_users_guest_token ON users (guest_token)
  WHERE guest_token IS NOT NULL;
